CREATE TABLE IF NOT EXISTS `backup_targets` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `type` TEXT NOT NULL, `endpoint` TEXT NOT NULL, `basePath` TEXT NOT NULL, `username` TEXT NOT NULL, `password` TEXT NOT NULL, `accessKey` TEXT NOT NULL, `secretKey` TEXT NOT NULL, `sessionToken` TEXT NOT NULL, `bucket` TEXT NOT NULL, `region` TEXT NOT NULL, `pathStyle` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
